entries[449888] = { ["name"] = "Giftsperrfeuer", ["text"] = "40 Meter Reichweite\nSofort\nDer Zaubernde schleudert einen Giftblitz auf sein aktuelles Ziel, fügt diesem Naturschaden zu und vergiftet es, sodass es 5 Sek. lang alle 1 Sek. zusätzlichen Naturschaden erleidet." }
