entries[450184] = { ["name"] = "Größere Ausrichtung", ["text"] = "[ Inkarnation: Erwählter der Elune : 'Inkarnation: Erwählter der Elune' / 'Himmlische Ausrichtung'] dauert 40% länger an.\n\nWährend [ Inkarnation: Erwählter der Elune : 'Inkarnation: Erwählter der Elune' / 'Himmlische Ausrichtung'] erhöht 'Sonnenfinsternis' den verursachten Naturschaden um zusätzliche 8% und Mondfinsternis den verursachten Arkanschaden um zusätzliche 8%." }
