entries[450283] = { ["name"] = "Hammer des irdenen Meisters", ["text"] = "Wirken in 3.5 sek.\nTools: Schmiedehammer\nReagenzien:\nBarren der Schallenden Tiefen (2), Aufgeladene Legierung (10), Geheiligte Legierung (10), Eisenklauenlegierung (10)\nBeruf:\nSchmiedekunst von Khaz Algar (100)\n\nHammer des irdenen Meisters\nWird beim Aufheben gebunden\nBenutzen: Repariert eine Waffe oder ein Plattenrüstungsteil, auf deren bzw. dessen Reparatur Ihr Euch spezialisiert habt.\nBenötigt Schmiedekunst von Khaz Algar\n(25)" }
entries[450291] = { ["name"] = "Kerngeschmiedeter Reparaturhammer", ["text"] = "Wirken in 3.5 sek.\nTools: Schmiedehammer\nReagenzien:\nBismut (10), Eisenklauenerz (2)\nOptionale Reagenzien:\nSchmiedezubehör (#382)\nBerufsausbilder:\nSchmiedekunst von Khaz Algar (5)\nKosten:\n80\n\nKerngeschmiedeter Reparaturhammer\nBenutzen: Repariert eine Waffe oder ein Plattenrüstungsteil vollständig. Wird bei Benutzung verbraucht.\n70\nBenötigt Schmiedekunst von Khaz Algar\n(1)" }
entries[450292] = { ["name"] = "Kerngeschmiedeter Dietrich", ["text"] = "Wirken in 3.5 sek.\nTools: Schmiedehammer\nReagenzien:\nBismut (8), Eisenklauenerz (4)\nOptionale Reagenzien:\nSchmiedezubehör (#382)\nVerkäufer:\nWelthändler von Khaz Algar\nKosten:\n150\n1500\n\nKerngeschmiedeter Dietrich\nBenutzen: Ermöglicht das Öffnen von Schlössern, die eine Fertigkeit von bis zu 80 im Schlossknacken benötigen. Dieser Vorgang verbraucht den Dietrich." }
