entries[450340] = { ["name"] = "Vxs Frostschlitzen", ["text"] = "Unbegrenzte Reichweite\nSofort\nÖffnet den Beutel und zückt die Schattenklinge von Nx, um schnell auf Gegner vor Euch loszugehen und allen getroffenen Gegnern ( 1 * 585 ) Schattenschaden zuzufügen.\n\nIhr könnt den Beutel bis zu zwei weitere Male innerhalb von 20 Sek. benutzen, bevor er sich selbst versiegelt und seinen Inhalt magisch auflädt." }
