entries[450356] = { ["name"] = "Den Kosmos berühren", ["text"] = "Beim Einsatz von 'Zorn' während einer 'Finsternis' besteht eine Chance von 18%, dass Euer nächster Einsatz von 'Sternensog' oder 'Sternenregen' kostenlos ist.\n\nBeim Einsatz von 'Sternenfeuer' während einer 'Finsternis' besteht eine Chance von 25%, dass Euer nächster Einsatz von 'Sternensog' oder 'Sternenregen' kostenlos ist." }
