entries[450362] = { ["name"] = "Instabile Infusion", ["text"] = "Unbegrenzte Reichweite\nSofort\nWellen schattenhafter Energie gehen alle 7.5 Sek. vom schwarzbluterfüllten Brutverderber aus, die allen Spielercharakteren 287816 Schattenschaden zufügen und die nächsten 490734 erhaltene Heilung absorbieren. Zusätzlich werden alle 7.5 Sek. Wellen von ' Widerwärtige Entladung ' freigesetzt." }
entries[450364] = { ["name"] = "Suchskarabäen", ["text"] = "Unbegrenzte Reichweite\nWirken in 2 sek.\nBenötigt Waffen\nVerschießt Skarabäen auf einen Gegner, die körperlichen Schaden verursachen." }
