entries[450369] = { ["name"] = "Schildwache", ["text"] = "Eure Angriffe haben eine Chance, 'Wächter' auf das Ziel anzuwenden, bis zu 10-mal stapelbar.\n\nWenn 'Wächter' mehr als 3 Stapel hat, hat die Anwendung von 'Wächter' eine Chance, eine Implosion auszulösen. Dadurch wird jede Sekunde ein Stapel des Ziels verbraucht, um (78.3% der Angriffskraft) Arkanschaden zu verursachen." }
entries[450372] = { ["name"] = "Strahlendes Echo" }
entries[450373] = { ["name"] = "Kein Blick zurück", ["text"] = "Wann immer 'Wachsamer Schütze' einem Gegner Schaden zufügt, erhaltet Ihr einen Absorptionsschild, der 1.0% Eurer maximalen Gesundheit entspricht, bis zu 10%." }
entries[450374] = { ["name"] = "Extrapolierte Schüsse", ["text"] = "Wenn Ihr ein Ziel, das derzeit nicht von 'Wachsamer Schütze' betroffen ist, mit 'Wachsamer Schütze' belegt, erhält es 1 zusätzlichen Stapel." }
entries[450375] = { ["name"] = "Wächterpräzision", ["text"] = "Treffsicherheit\n'Gezielter Schuss' und 'Schnellfeuer' verursachen 5% mehr Schaden.\n\nÜberleben\n'Raptorstoß', 'Mungobiss' und 'Lauffeuerbombe' verursachen 10% mehr Schaden." }
entries[450376] = { ["name"] = "Feuern und Nachladen", ["text"] = "Wenn Ihr ein Ziel mit 'Wachsamer Schütze' belegt, besteht eine Chance von 15%, dass Ihr es mit einem zweiten Stapel belegt." }
entries[450377] = { ["name"] = "Strahlendes Echo" }
entries[450378] = { ["name"] = "Seitenlinie", ["text"] = "Wenn 'Wachsamer Schütze' beginnt, Schaden zu verursachen, wird das Ziel 3 Sek. lang um 40% verlangsamt." }
entries[450379] = { ["name"] = "Belebender Impuls", ["text"] = "Wann immer 'Wachsamer Schütze' einem Gegner Schaden zufügt, besteht eine Chance von 15%, 5 Fokus zu erzeugen.\n\nDie Chance sinkt mit jedem zusätzlichen implodierenden Effekt 'Wachsamer Schütze', von denen Gegner betroffen sind." }
entries[450380] = { ["name"] = "Chiwelle" }
entries[450381] = { ["name"] = "Augen zu", ["text"] = "Überleben\nNachdem 'Koordinierter Angriff' aktiviert wurde, belegen 8 Sek. lang alle Fähigkeiten ihre Ziele garantiert mit 'Wachsamer Schütze'.\n\nTreffsicherheit\nNachdem 'Volltreffer' aktiviert wurde, belegen 8 Sek. lang alle Fähigkeiten ihre Ziele garantiert mit 'Wachsamer Schütze'." }
entries[450382] = { ["name"] = "Strahlendes Echo" }
entries[450383] = { ["name"] = "Symphonisches Arsenal", ["text"] = "Treffsicherheit\nEuer 'Mehrfachschuss' entlädt arkane Energie von allen Zielen, die von Eurem Effekt 'Wachsamer Schütze' betroffen sind. Fügt bis zu 5 Zielen innerhalb von 8 Metern um mit Eurem Effekt 'Wachsamer Schütze' belegte Ziele [(38.64% der Angriffskraft)] Arkanschaden zu.\n\nÜberleben\nEuer 'Mehrfachschuss' und 'Schlachten' entladen arkane Energie von allen Zielen, die von Eurem Effekt 'Wachsamer Schütze' betroffen sind. Fügt bis zu 5 Zielen innerhalb von 8 Metern um mit Eurem Effekt 'Wachsamer Schütze' belegte Ziele (90% der Angriffskraft) Arkanschaden zu.\n\n(100ms Abklingzeit)" }
entries[450384] = { ["name"] = "Überwachung", ["text"] = "Wenn ein Ziel, das von mehr als 3 Eurer Stapel von 'Wachsamer Schütze' betroffen ist, unter 20% Gesundheit fällt, implodieren alle Schwächungen durch 'Wachsamer Schütze'.\n\nDieser Effekt kann pro Ziel nur einmal alle 15 Sek. auftreten." }
entries[450385] = { ["name"] = "Lunarsturm", ["text"] = "Überleben\nAlle 30 Sek. wird die Abklingzeit von 'Lauffeuerbombe' zurückgesetzt und Euer nächster Einsatz von 'Lauffeuerbombe' verschießt auch einen Himmelspfeil, der am Standort des Ziels einen 'Lunarsturm' mit einem Radius von 12 Metern beschwört und so (100% der Angriffskraft) Arkanschaden verursacht.\n\nFür die nächsten 12 Sek. erleidet ein zufälliger Gegner innerhalb Eures Lunarsturms, der von 'Wachsamer Schütze' betroffen ist, alle 0.4 Sek. (93.75% der Angriffskraft) Arkanschaden. Alle Ziele, die von diesem Effekt getroffen werden, erleiden 8 Sek. lang 10% mehr Schaden durch Euch und Euren Begleiter.\n\nTreffsicherheit\nAlle 30 Sek. wird die Abklingzeit von 'Schnellfeuer' zurückgesetzt und Euer nächster Einsatz von 'Schnellfeuer' verschießt auch einen Himmelspfeil, der am Standort des Ziels einen 'Lunarsturm' mit einem Radius von 12 Metern beschwört und so (100% der Angriffskraft) Arkanschaden verursacht.\n\nFür die nächsten 12 Sek. erleidet ein zufälliger Gegner innerhalb Eures Lunarsturms, der von 'Wachsamer Schütze' betroffen ist, alle 0.4 Sek. (93.75% der Angriffskraft) Arkanschaden. Alle Ziele, die von diesem Effekt getroffen werden, erleiden 8 Sek. lang 10% mehr Schaden durch Euch.\n\n(15s Abklingzeit)" }
