entries[450405] = { ["name"] = "Leerenschlag", ["text"] = "Schatten\n'Entropischer Riss' wertet 'Gedankenschlag' zu 'Leerenschlag' auf, während er aktiv ist.\n\nLeerenschlag :\nSendet einen Stoß kosmischer Leerenenergie auf den Gegner, der (210% der Zaubermacht) Schattenschaden verursacht. [ Schatten : Erzeugt 6 Wahnsinn. ]\nDisziplin\n'Entropischer Riss' wertet 'Heilige Pein' zu 'Leerenschlag' auf, während er aktiv ist.\n\nLeerenschlag :\nSendet einen Stoß kosmischer Leerenenergie auf den Gegner, der (110% der Zaubermacht) Schattenschaden verursacht. [ Schatten : Erzeugt 0 Wahnsinn. ]" }
