entries[450510] = { ["name"] = "Dämonenseele", ["text"] = "100 Meter Reichweite\nSofort\nEin dämonisches Wesen wohnt in Eurer Seele und ermöglicht es Euch zu entdecken, ob ein Seelensplitter bei seiner Entstehung über eine saftige Seele verfügt.\n\nEine saftige Seele ermächtigt Euren nächsten Einsatz von [ Gebrechen : 'Unheilvolle Euphorie', erhöht seinen Schaden um 20% und entfesselt Eure dämonische Seele, um (176.618% der Zaubermacht) zusätzlichen Schattenschaden zu verursachen /\n\nDämonologie\n'Hand von Gul'dan', erhöht seinen Schaden um 60% und entfesselt Eure dämonische Seele, um (176.618% der Zaubermacht) zusätzlichen Schattenschaden zu verursachen ]" }
