entries[450674] = { ["name"] = "Foliant der Hingabe des Lichts", ["text"] = "Ihr öffnet im Kampf den Foliant und lest \"Die 50 Verse der inneren Abhärtung\". Erhöht Eure Rüstung um 80 und gewährt Euren Angriffen eine Chance, einen Schutz zu erzeugen, der 1025 Magieschaden absorbiert. Anschließend seht Ihr die Passagen bis zum nächsten Kapitel durch.\n\nEinsatz: Seht sorgfältig die Passagen bis zum nächsten Kapitel durch und lest mit erhöhtem Strahlen." }
entries[450675] = { ["name"] = "Grimmwebenausbruch", ["text"] = "40 Meter Reichweite\nSofort\nDer Zaubernde webt Runen aus Spinnweben und beschwört einen instabilen Ball aus Spinnweben über der Position des Ziels. Beim Aufprall platzt er explosionsartig und fügt den getroffenen Spielercharakteren Naturschaden zu." }
