entries[450677] = { ["name"] = "Berstende Runen", ["text"] = "Wirken in 1.5 sek. 8 sek. Abklingzeit\nOrta beschwört 5 Sek. lang alle 1 Sek. eine Rune der Verwüstung. Wenn sie ausgelöst werden, betäuben diese Runen den auslösenden Spielercharakter und fügen ihm zusätzlich alle 1 Sek. 261400 Feuerschaden zu. Hält 8 Sek. lang an." }
