entries[450921] = { ["name"] = "Zuwachs des Obersten Sprechers", ["text"] = "100 Meter Reichweite\nSofort\nLädt den Kristall auf, um einen Spalt zu beschwören, der Gegnern in der Nähe Energie entzieht und im Verlauf von 6 Sek. ( 1 * 2246 * 6) Schattenschaden verursacht.\n\nWenn der Spalt kollabiert, kehrt die entzogene Energie zu Euch zurück, um Eure Intelligenz 20 Sek. lang um 9 zu erhöhen und für jeden getroffenen Gegnern weiter zu steigern." }
