entries[450923] = { ["name"] = "Explodierendes Licht", ["text"] = "5 Energie pro Sek. 100 Meter Reichweite\nSofort\nBeschwört eine berstende Lichtbrut, die ihre Gesundheit opfert, um Lichtstöße zu entfesseln, die 1446 Heiligschaden verursachen, der alle 2 Sekunden auf Gegner in der Nähe aufgeteilt wird, solange die Brut lebt." }
entries[450924] = { ["name"] = "Griff des Berges", ["text"] = "Sofort 8.5 sek. Abklingzeit\nOrta ergreift Spielercharaktere in der Nähe, zerquetscht sie mit seinem Griff und fügt ihnen 697066 körperlichen Schaden zu. Sein Griff bringt Spielercharaktere zum Schweigen und verursacht alle 348533 Sek. 1.5 körperlichen Schaden." }
