entries[450959] = { ["name"] = "Jankys Feinstes", ["text"] = "Sofort\nBietet ein tröstendes Licht selbst in der dunkelsten Mine. Erhöht die Bewegungsgeschwindigkeit um 25% und verringert den erlittenen Schattenschaden um 25%.\nHält 10 Min. lang an.\nNur in Khaz Algar nutzbar." }
entries[450960] = { ["name"] = "Leerenimpuls", ["text"] = "100 Meter Reichweite\nSofort\nEure Angriffe haben eine Chance, den Pakt anzurufen und eine Explosion auszulösen, die ( 1 * 897 ) Schattenschaden verursacht, die auf Gegner in der Nähe aufgeteilt werden, und Euer Tempo 10 Sek. lang um 36 erhöht.\n\nEuer Tod beendet den Pakt und führt zu einer gewaltigen Explosion." }
entries[450961] = { ["name"] = "Mächtiger Sturmangriff", ["text"] = "100 Meter Reichweite\nSofort\nFügt einem Gegner Schaden in Höhe von 0% des normalen Waffenschadens zu und betäubt ihn für 2 Sek." }
entries[450962] = { ["name"] = "Leerenpaktstein", ["text"] = "Sofort\nEure Angriffe haben eine Chance, den Pakt anzurufen und eine Explosion auszulösen, die ( 1 * 897 ) Schattenschaden verursacht, die auf Gegner in der Nähe aufgeteilt werden, und Euer Tempo 10 Sek. lang um 36 erhöht.\n\nEuer Tod beendet den Pakt und führt zu einer gewaltigen Explosion." }
entries[450964] = { ["name"] = "Heilige Brigade", ["text"] = "30 Meter Reichweite\nSofort 5 min Abklingzeit\nWirft einen Klecks heiliges Öl, das eine Explosion auslöst, die allen Gegnern innerhalb von 6 Metern 29775 Heiligfeuerschaden zufügt, sie zurückstößt und ihre Bewegungsgeschwindigkeit 8 Sek. lang um 30% verringert.\n\nDer Rückstoßeffekt ist bei gegnerischen Spielercharakteren wirksamer." }
