entries[450969] = { ["name"] = "Endloser Schwarm", ["text"] = "100 Meter Reichweite\nSofort\nDie Drüse setzt Pheromone frei, die einen endlosen Schwarm von Insekten anlocken, die Euch umkreisen. Wenn Ihr Schaden erleidet, habt Ihr eine hohe Chance auf einen Gegenschlag, der über 6 Sek. ( 69 * 6) Naturschaden verursacht und den Euch zugefügten Schaden um 96 reduziert." }
