entries[450974] = { ["name"] = "Funkenspuckerkerze", ["text"] = "Sofort\nCa. 3.5 Procs pro Minute\nVerursacht beim Angreifen gelegentlich zusätzlichen Feuerschaden.\nHält 10 Min. lang an.\nNur in Khaz Algar nutzbar." }
