entries[450978] = { ["name"] = "Lunarsturm", ["text"] = "100 Meter Reichweite\nSofort\nÜberleben\nAlle 30 Sek. wird die Abklingzeit von 'Lauffeuerbombe' zurückgesetzt und Euer nächster Einsatz von 'Lauffeuerbombe' verschießt auch einen Himmelspfeil, der am Standort des Ziels einen 'Lunarsturm' mit einem Radius von 12 Metern beschwört und so (100% der Angriffskraft) Arkanschaden verursacht.\n\nFür die nächsten 12 Sek. erleidet ein zufälliger Gegner innerhalb Eures Lunarsturms, der von 'Wachsamer Schütze' betroffen ist, alle 0.4 Sek. (93.75% der Angriffskraft) Arkanschaden. Alle Ziele, die von diesem Effekt getroffen werden, erleiden 8 Sek. lang 10% mehr Schaden durch Euch und Euren Begleiter.\n\nTreffsicherheit\nAlle 30 Sek. wird die Abklingzeit von 'Schnellfeuer' zurückgesetzt und Euer nächster Einsatz von 'Schnellfeuer' verschießt auch einen Himmelspfeil, der am Standort des Ziels einen 'Lunarsturm' mit einem Radius von 12 Metern beschwört und so (100% der Angriffskraft) Arkanschaden verursacht.\n\nFür die nächsten 12 Sek. erleidet ein zufälliger Gegner innerhalb Eures Lunarsturms, der von 'Wachsamer Schütze' betroffen ist, alle 0.4 Sek. (93.75% der Angriffskraft) Arkanschaden. Alle Ziele, die von diesem Effekt getroffen werden, erleiden 8 Sek. lang 10% mehr Schaden durch Euch." }
entries[450979] = { ["name"] = "Stolz von Pandaria", ["text"] = "'Prügelladung' hat eine zusätzliche Chance von 15%, kritische Treffer zu landen." }
entries[450980] = { ["name"] = "Existenz zertrümmern", ["text"] = "Kanalisiert (Wirken in 11 min)\nTakazj hüllt sich in einen Schild, der 392587563 Schaden absorbiert.\n\nSolange der Schild anhält, entfesselt Takazj alle 16 Sek. ' Entropischer Beschuss ' und spinnt Netzkegel in der Kammer. Diese Netze verringern die Bewegungsgeschwindigkeit von Spielercharakteren um 20% und fügen Spielercharakteren im Effektbereich alle 1 Sek. 230253 Schattenschaden zu.\n\nDie Netze explodieren regelmäßig, was Spielercharakteren 8058841 Schattenschaden zufügt, sie zurückstößt und ihnen 12 Sek. lang alle 3 Sek. 1381516 zusätzlichen Schattenschaden zufügt." }
entries[450981] = { ["name"] = "Endloser Schwarm" }
entries[450982] = { ["name"] = "Starker Einschlag", ["text"] = "Gegner, die innerhalb von 10 Sek. nach Schaden durch 'Prügelhagel' sterben, explodieren und fügen unkontrollierten Gegnern innerhalb von 8 Metern (100% der Angriffskraft) körperlichen Schaden zu." }
entries[450983] = { ["name"] = "Leerenschlag", ["text"] = "-6 Wahnsinn / 0.25% von Grundmana 40 Meter Reichweite\nWirken in 1.5 sek. 9 sek. Abklingzeit\n1 Aufladung\nSendet einen Stoß kosmischer Leerenenergie auf den Gegner, der (210% der Zaubermacht) Schattenschaden verursacht. [ Schatten : Erzeugt 6 Wahnsinn. ]" }
entries[450984] = { ["name"] = "Schutz und Dienst", ["text"] = "Euer 'Beleben' heilt Euch immer um zusätzliche 30% des Gesamtwerts." }
entries[450985] = { ["name"] = "Mit gutem Beispiel voran", ["text"] = "'Chistoß', 'Chiwelle' und 'Schadensumleitung' heilen Euch nun um 20% des verursachten Schadens." }
entries[450986] = { ["name"] = "Allen Widrigkeiten zum Trotz", ["text"] = "Euer 'Prügelhagel' erhöht 5 Sek. lang Eure Beweglichkeit um 1%. Bis zu 20-mal stapelbar." }
entries[450987] = { ["name"] = "Auge des Veteranen", ["text"] = "Das gleiche Ziel innerhalb von 2 Sek. 5-mal zu treffen, gewährt 1% Tempo, bis zu 10 Stapel." }
entries[450988] = { ["name"] = "Einer gegen Viele", ["text"] = "Der verursachte Schaden durch 'Furorfäuste' und 'Fasshieb' zählt doppelt für die Erzeugung von 'Prügelladung'.\n\nSchaden von 'Furorfäuste' um 20% erhöht.\nSchaden von 'Fasshieb' um 35% erhöht." }
entries[450989] = { ["name"] = "Effektives Training", ["text"] = "Braumeister\nFähigkeiten, die Energie verbrauchen, verursachen 20% mehr Schaden.\nPro 50 Einheiten verbrauchter Energie wird die Abklingzeit von 'Waffen der Ordnung' um 1 Sek. verringert.\n\nWindläufer\nFähigkeiten, die Energie verbrauchen, verursachen 40% mehr Schaden.\nPro 50 Einheiten verbrauchter Energie wird die Abklingzeit von 'Sturm, Erde und Feuer' um 1 Sek. verringert." }
entries[450990] = { ["name"] = "Präzise Kampfkunst", ["text"] = "Eure Angriffe durchdringen 12% Rüstung." }
entries[450991] = { ["name"] = "Wirbelnder Stahl", ["text"] = "Beschwört 'Wirbelnder Stahl', wenn Eure Gesundheit auf weniger als 50% fällt, um Eure Parierchance und Vermeidung 6 Sek. lang um 15% zu erhöhen.\n\nDieser Effekt kann höchstens einmal alle 180 Sek. auftreten.\n(3Min. Abklingzeit)" }
entries[450992] = { ["name"] = "Vorausschauendes Training", ["text"] = "Wenn Ihr einem Angriff ausweicht oder ihn pariert, wird der erlittene Schaden für die nächsten 6 Sek. um 10% verringert." }
entries[450993] = { ["name"] = "Wachsame Beobachtung", ["text"] = "'Blackout-Tritt' verursacht 20% zusätzlichen kritischen Schaden und erhöht den Schaden Eurer nächsten Reihe von 'Prügelladung' um 10%." }
entries[450994] = { ["name"] = "Weisheit der Mauer", ["text"] = "Nach jeweils 10 Einsätzen von 'Prügelhagel' ereilt Euch die 'Weisheit der Mauer' und gewährt Euch 16 Sek. lang einen dieser Effekte.\n\nKritischer Trefferschaden um 30% erhöht.\n\nAusweich- und kritische Trefferchance um 25% Eures Vielseitigkeitsbonus erhöht.\n\n'Prügelhagel' fügt allen unkontrollierten Gegnern innerhalb von 6 Metern (160% der Angriffskraft) Schattenschaden zu.\n\nErhöht den Effekt Eurer Meisterschaft um 25%." }
entries[450995] = { ["name"] = "Funkenspuckerkerze", ["text"] = "100 Meter Reichweite\nSofort\nVerursacht beim Angreifen gelegentlich zusätzlichen Feuerschaden." }
