entries[451018] = { ["name"] = "Dunkle Energie", ["text"] = "Schatten\n'Leerenstrom' kann in Bewegung eingesetzt werden. Während 'Entropischer Riss' aktiv ist, bewegt Ihr Euch 20% schneller.\n\nDisziplin\nWährend 'Entropischer Riss' aktiv ist, bewegt Ihr Euch 20% schneller." }
entries[451021] = { ["name"] = "Prügelladung", ["text"] = "Sofort\nPro [(Angriffskraft * 6.25 * (1 + Vielseitigkeit))] Schaden, die Ihr verursacht, wird eine Aufladung von 'Prügelladung' erzeugt. Pro 240 Energie, die Ihr verbraucht, werden alle Aufladungen von 'Prügelladung' entfesselt und verursachen pro Aufladung (60% der Angriffskraft) körperlichen Schaden." }
