entries[451024] = { ["name"] = "Überwältigende Kraft", ["text"] = "Braumeister\n'Tritt der aufgehenden Sonne', 'Blackout-Tritt', und 'Tigerklaue' fügen Gegnern in einer Linie vor Euch 25% zusätzlichen Schaden zu. Nach dem 5. Ziel ist der Schaden verringert.\n\nNebelwirker\n'Tritt der aufgehenden Sonne', 'Blackout-Tritt', und 'Tigerklaue' fügen Gegnern in einer Linie vor Euch 5% zusätzlichen Schaden zu. Nach dem 5. Ziel ist der Schaden verringert." }
